package vn.eventplatform.ad.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.ByteArrayResource; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.util.*; import org.springframework.web.client.RestClient; import org.springframework.web.multipart.MultipartFile; import vn.eventplatform.common.dto.ErrorCode; import vn.eventplatform.common.exception.AppException; import java.io.IOException; import java.util.Map;
@Service public class CloudinaryUploadService { private final String cloud; private final String preset; private final RestClient client=RestClient.create(); public CloudinaryUploadService(@Value("${cloudinary.cloud-name}")String cloud,@Value("${cloudinary.upload-preset}")String preset){this.cloud=cloud;this.preset=preset;} public String upload(MultipartFile file){if(cloud.isBlank()||preset.isBlank())throw new AppException(ErrorCode.BAD_REQUEST,"Cloudinary chưa được cấu hình");try{MultiValueMap<String,Object> body=new LinkedMultiValueMap<>();body.add("upload_preset",preset);body.add("file",new ByteArrayResource(file.getBytes()){public String getFilename(){return file.getOriginalFilename();}});Map result=client.post().uri("https://api.cloudinary.com/v1_1/{cloud}/image/upload",cloud).contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Map.class);Object url=result==null?null:result.get("secure_url");if(url==null)throw new AppException(ErrorCode.BAD_REQUEST,"Cloudinary không trả URL ảnh");return url.toString();}catch(IOException e){throw new AppException(ErrorCode.BAD_REQUEST,"Không thể đọc file ảnh");}}}
